describe("extraUnsealPasswords", () => {
  const nova = "nova-" + "x".repeat(43);
  const antiga = "antiga-" + "y".repeat(42);
  const outra = "outra-" + "z".repeat(43);
  const errada = "errada-" + "w".repeat(42);
  const curta = "curta";

  const config = (overrides: Partial<SessionConfig> = {}): SessionConfig => ({
    name: "h3-extra",
    password: nova,
    generateId: () => "fresh-1",
    ...overrides,
  });
  const sealWith = (password: string, data: object, iterations?: number) =>
    seal(data, password, {
      ...sealDefaults,
      encryption: {
        ...sealDefaults.encryption,
        iterations: iterations ?? sealDefaults.encryption.iterations,
      },
      integrity: {
        ...sealDefaults.integrity,
        iterations: iterations ?? sealDefaults.integrity.iterations,
      },
    });
  const sealedPayload = (password: string, iterations?: number) =>
    sealWith(password, { id: "s1", createdAt: Date.now(), data: { user: "alice" } }, iterations);
  const registerSession = (cfg: SessionConfig) => {
    t.app.get("/extra", async (event) => {
      const session = await useSession(event, cfg);
      return { id: session.id, data: session.data };
    });
  };
  const sealedOf = (res: Response) =>
    decodeURIComponent(res.headers.getSetCookie()[0].match(/h3-extra=([^;]+)/)![1]);

  it("seals only with password", async () => {
    registerSession(config({ extraUnsealPasswords: [antiga] }));
    const res = await t.fetch("/extra");
    const sealed = sealedOf(res);
    expect(await unseal(sealed, nova, sealDefaults)).toMatchObject({ id: "fresh-1" });
    await expect(unseal(sealed, antiga, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("does not try the extras when the primary password opens the cookie", async () => {
    registerSession(config({ extraUnsealPasswords: [antiga] }));
    const primary = await sealedPayload(nova);
    const extra = await sealedPayload(antiga);
    const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");

    deriveBits.mockClear();
    await t.fetch("/extra", { headers: { Cookie: `h3-extra=${primary}` } });
    // Opening takes two derivations (integrity and encryption), with no extra attempts
    expect(deriveBits).toHaveBeenCalledTimes(2);

    deriveBits.mockClear();
    await t.fetch("/extra", { headers: { Cookie: `h3-extra=${extra}` } });
    // The failed primary attempt (including its legacy try) costs more, then the
    // extra opens the cookie and the session is resealed with the primary
    expect(deriveBits).toHaveBeenCalledTimes(6);
    deriveBits.mockRestore();
  });

  it("opens with an extra password and returns the original data", async () => {
    registerSession(config({ extraUnsealPasswords: [antiga] }));
    const res = await t.fetch("/extra", {
      headers: { Cookie: `h3-extra=${await sealedPayload(antiga)}` },
    });
    expect(await res.json()).toMatchObject({ id: "s1", data: { user: "alice" } });
  });

  it("tries the extra passwords in declared order", async () => {
    registerSession(config({ extraUnsealPasswords: [errada, antiga] }));
    const res = await t.fetch("/extra", {
      headers: { Cookie: `h3-extra=${await sealedPayload(antiga)}` },
    });
    expect(await res.json()).toMatchObject({ id: "s1", data: { user: "alice" } });
  });

  it("starts an empty session when no password opens the cookie", async () => {
    registerSession(config({ extraUnsealPasswords: [antiga] }));
    const res = await t.fetch("/extra", {
      headers: { Cookie: `h3-extra=${await sealedPayload(outra)}` },
    });
    const body = await res.json();
    expect(body.id).toBe("fresh-1");
    expect(body.data).toEqual({});
  });

  it("propagates the error of the primary password", async () => {
    await expect(
      unsealSession(
        {} as any,
        config({ extraUnsealPasswords: [antiga] }),
        await sealedPayload(outra),
      ),
    ).rejects.toThrow("Bad hmac value");
  });

  it("reseals a legacy session opened with an extra password", async () => {
    registerSession(config({ extraUnsealPasswords: [antiga] }));
    const sealed = await sealedPayload(antiga, 1);

    const unsealed = await unsealSession({} as any, config({ extraUnsealPasswords: [antiga] }), sealed);
    expect(unsealed).toMatchObject({ id: "s1", data: { user: "alice" } });
    expect((unsealed as any)[kLegacySeal]).toBe(true);

    const res = await t.fetch("/extra", { headers: { Cookie: `h3-extra=${sealed}` } });
    expect(await res.json()).toMatchObject({ id: "s1", data: { user: "alice" } });
    expect(res.headers.getSetCookie()).toHaveLength(1);
    expect(await unseal(sealedOf(res), nova, sealDefaults)).toMatchObject({ id: "s1" });
  });

  it("reseals a session opened with an extra password under the primary", async () => {
    registerSession(config({ extraUnsealPasswords: [antiga] }));
    const res = await t.fetch("/extra", {
      headers: { Cookie: `h3-extra=${await sealedPayload(antiga)}` },
    });
    expect(res.headers.getSetCookie()).toHaveLength(1);
    const resealed = sealedOf(res);
    expect(await unseal(resealed, nova, sealDefaults)).toMatchObject({
      id: "s1",
      data: { user: "alice" },
    });
    await expect(unseal(resealed, antiga, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("does not reseal a session read from the header", async () => {
    registerSession(config({ extraUnsealPasswords: [antiga] }));
    const res = await t.fetch("/extra", {
      headers: { "x-h3-extra-session": await sealedPayload(antiga) },
    });
    expect(await res.json()).toMatchObject({ id: "s1", data: { user: "alice" } });
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  it("a short extra password does not block the valid ones after it", async () => {
    registerSession(config({ extraUnsealPasswords: [curta, antiga] }));
    const res = await t.fetch("/extra", {
      headers: { Cookie: `h3-extra=${await sealedPayload(antiga)}` },
    });
    expect(await res.json()).toMatchObject({ id: "s1", data: { user: "alice" } });
  });

  it("an extra password does not extend maxAge", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      registerSession(config({ maxAge: 60, extraUnsealPasswords: [antiga] }));
      const sealed = await sealedPayload(antiga);
      vi.setSystemTime(t0 + 61_000);
      const res = await t.fetch("/extra", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "fresh-1", data: {} });
    } finally {
      vi.useRealTimers();
    }
  });

  it("a repeated password still opens the session", async () => {
    registerSession(config({ extraUnsealPasswords: [nova] }));
    const res = await t.fetch("/extra", {
      headers: { Cookie: `h3-extra=${await sealedPayload(nova)}` },
    });
    expect(await res.json()).toMatchObject({ id: "s1", data: { user: "alice" } });
  });

  it("an empty list behaves as no extra passwords", async () => {
    registerSession(config({ extraUnsealPasswords: [] }));
    const res = await t.fetch("/extra", {
      headers: { Cookie: `h3-extra=${await sealedPayload(antiga)}` },
    });
    expect(await res.json()).toMatchObject({ id: "fresh-1", data: {} });
  });
});

